package org.xmlet.htmlflow.datastar.expressions

import org.xmlet.htmlflow.datastar.expressions.ast.JsExpr
import org.xmlet.htmlflow.datastar.expressions.ast.JsRenderer

/**
 * Represents a [DataStarExpression] that is generated by an operation provided by the DSL,
 * rather than by a Datastar action, such as the infix JavaScript operator helpers.
 *
 * Composition retains the AST without rendering it. Reading [syntax] or calling [toString]
 * renders on demand; literal values are serialized at that point, not cached at construction.
 */
class DataStarExpressionOp internal constructor(
    internal val node: JsExpr,
) : DataStarExpression() {
    override val syntax: String
        get() = JsRenderer.render(node)
}
